def range_compress(values):
    if not values:
        return []
    uniq = sorted(set(values))
    n = len(uniq)
    if n == 1:
        return [uniq[0], uniq[0]]
    result = []
    i = 0
    while i < n:
        start = uniq[i]
        j = i + 1
        while j < n and uniq[j] == uniq[j - 1] + 1:
            j += 1
        end = uniq[j - 1]
        if end > start:
            result.append([start, end])
        else:
            result.append([start, start])
        i = j
    return result
